if(isset($_POST['login_token'])){if(Auth::adminLogin((string)$_POST['login_token'])){session_regenerate_id(true);$_SESSION['ogpn_admin']=true;Auth::csrfToken();header('Location: console.php');exit;}else{$error='Token incorrect.';}}
if(isset($_GET['logout'])){session_destroy();header('Location: console.php');exit;}
if(empty($_SESSION['ogpn_admin'])){?><!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>OGPN-BOT — Connexion</title><body><h1>Console OGPN-BOT 2.0</h1><?php if(isset($error))echo '<p>'.htmlspecialchars($error).'</p>';?><form method="post"><input type="password" name="login_token" autocomplete="current-password" required><button>Connexion</button></form></body></html><?php exit;}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save_settings'])){try{Auth::requireCsrf($_POST['csrf']??null);$high=max(100,(int)($_POST['high']??20000));$low=max(0,(int)($_POST['low']??12000));if($low>=$high)throw new RuntimeException('Le seuil bas doit être inférieur au seuil haut.');Settings::set($pdo,'queue.high_threshold',$high);Settings::set($pdo,'queue.low_threshold',$low);Settings::set($pdo,'features.discovery_enabled',isset($_POST['discovery']));Settings::set($pdo,'features.scan_enabled',isset($_POST['scan']));Settings::set($pdo,'features.emergency_stop',isset($_POST['stop']));$msg='Configuration enregistrée.';}catch(Throwable $e){$error=$e->getMessage();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['toggle_worker'])){try{Auth::requireCsrf($_POST['csrf']??null);$id=(string)($_POST['worker_id']??'');$pdo->prepare('UPDATE v2_workers SET enabled=1-enabled WHERE worker_id=?')->execute([$id]);$msg='État du worker modifié.';}catch(Throwable $e){$error=$e->getMessage();}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['update_worker'])){try{Auth::requireCsrf($_POST['csrf']??null);$id=(string)($_POST['worker_id']??'');$role=(string)($_POST['role']??'');$capacity=(string)($_POST['capacity']??'');$capRaw=trim((string)($_POST['max_runs']??''));$cap=$capRaw===''?null:max(1,(int)$capRaw);if(!in_array($role,['discovery','scan','auto'],true)||!in_array($capacity,['low','medium','high'],true))throw new RuntimeException('Rôle ou capacité invalide.');$perms=['worker.plan'];if(in_array($role,['discovery','auto'],true))array_push($perms,'discovery.claim','discovery.ingest','discovery.fail');if(in_array($role,['scan','auto'],true))array_push($perms,'scan.claim','scan.ingest','scan.fail');$pdo->prepare('UPDATE v2_workers SET preferred_role=?,capacity=?,max_runs_per_day=?,permissions=? WHERE worker_id=?')->execute([$role,$capacity,$cap,json_encode($perms),$id]);$msg="Worker $id mis à jour.";}catch(Throwable $e){$error=$e->getMessage();}}
$d=Bootstrap::defaults();$m=Planner::metrics($pdo);$high=Settings::get($pdo,'queue.high_threshold',$d['queue']['high_threshold']);$low=Settings::get($pdo,'queue.low_threshold',$d['queue']['low_threshold']);$discovery=Settings::bool($pdo,'features.discovery_enabled',true);$scan=Settings::bool($pdo,'features.scan_enabled',true);$stop=Settings::bool($pdo,'features.emergency_stop',false);$mode=Settings::get($pdo,'orchestrator.mode','discovery');$workers=$pdo->query('SELECT worker_id,platform,preferred_role,capacity,enabled,max_runs_per_day,last_seen_at,last_action FROM v2_workers ORDER BY worker_id')->fetchAll();$runsToday=$pdo->query("SELECT worker_id,COUNT(*) c FROM v2_worker_runs WHERE started_at>=UTC_DATE() GROUP BY worker_id")->fetchAll(PDO::FETCH_KEY_PAIR);$csrf=Auth::csrfToken();
?><!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>Console OGPN-BOT</title><style>body{font:14px system-ui;max-width:1100px;margin:30px auto;padding:0 15px;color:#222}nav a{margin-right:15px}.cards{display:flex;gap:12px;flex-wrap:wrap}.card{border:1px solid #ddd;padding:12px 16px;border-radius:8px;min-width:150px}.n{font-size:24px;font-weight:700}table{border-collapse:collapse;width:100%}td,th{padding:7px;border-bottom:1px solid #ddd;text-align:left}fieldset{margin:20px 0;padding:15px}label{display:block;margin:8px 0}.ok{color:#176b35}.bad{color:#a21b1b}</style><nav><a href="console.php">Console</a><a href="diagnostic.php">Diagnostic</a><a href="activity.php">Activité</a><a href="?logout=1">Déconnexion</a></nav><h1>OGPN-BOT 2.0 consolidée RC1</h1><?php if(isset($msg))echo '<p class="ok">'.htmlspecialchars($msg).'</p>';if(isset($error))echo '<p class="bad">'.htmlspecialchars($error).'</p>';?><p>Mode courant : <strong><?=htmlspecialchars((string)$mode)?></strong></p><div class="cards"><div class="card"><div class="n"><?=$m['pending_new']?></div>Nouveaux en attente</div><div class="card"><div class="n"><?=$m['pending_rescan']?></div>Rescans dus</div><div class="card"><div class="n"><?=$m['cc_pending']?></div>Pages CC disponibles</div><div class="card"><div class="n"><?=$m['cc_failed']?></div>Jobs CC en erreur</div></div><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="save_settings" value="1"><fieldset><legend>Orchestration</legend><label>Seuil haut <input type="number" name="high" value="<?=htmlspecialchars((string)$high)?>"></label><label>Seuil bas <input type="number" name="low" value="<?=htmlspecialchars((string)$low)?>"></label><label><input type="checkbox" name="discovery" <?=$discovery?'checked':''?>> Découverte activée</label><label><input type="checkbox" name="scan" <?=$scan?'checked':''?>> Scan activé</label><label><input type="checkbox" name="stop" <?=$stop?'checked':''?>> Arrêt d’urgence</label><button>Enregistrer</button></fieldset></form><h2>Workers</h2><table><tr><th>ID</th><th>Plateforme</th><th>Rôle</th><th>Capacité</th><th>Actif</th><th>Runs aujourd'hui</th><th>Dernière activité</th><th>Dernière action</th><th>Basculer</th><th>Modifier</th></tr><?php foreach($workers as $w):$used=(int)($runsToday[$w['worker_id']]??0);$cap=$w['max_runs_per_day'];?><tr><td><?=htmlspecialchars($w['worker_id'])?></td><td><?=htmlspecialchars($w['platform'])?></td><td><?=htmlspecialchars($w['preferred_role'])?></td><td><?=htmlspecialchars($w['capacity'])?></td><td><?=$w['enabled']?'oui':'non'?></td><td><?=$cap!==null?"$used / $cap":"$used / illimité"?></td><td><?=htmlspecialchars($w['last_seen_at']?:'jamais')?></td><td><?=htmlspecialchars($w['last_action']?:'-')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="toggle_worker" value="1"><input type="hidden" name="worker_id" value="<?=htmlspecialchars($w['worker_id'])?>"><button><?=$w['enabled']?'Désactiver':'Activer'?></button></form></td><td><form method="post" style="display:flex;gap:4px;align-items:center"><input type="hidden" name="csrf" value="<?=htmlspecialchars($csrf)?>"><input type="hidden" name="update_worker" value="1"><input type="hidden" name="worker_id" value="<?=htmlspecialchars($w['worker_id'])?>"><select name="role"><?php foreach(['discovery','scan','auto'] as $r):?><option value="<?=$r?>" <?=$w['preferred_role']===$r?'selected':''?>><?=$r?></option><?php endforeach;?></select><select name="capacity"><?php foreach(['low','medium','high'] as $c):?><option value="<?=$c?>" <?=$w['capacity']===$c?'selected':''?>><?=$c?></option><?php endforeach;?></select><input type="number" name="max_runs" min="1" placeholder="illimité" value="<?=$cap!==null?(int)$cap:''?>" style="width:80px"><button>OK</button></form></td></tr><?php endforeach;?></table></html>
